    {
        "type": "statistic",
        "jurisdiction": "USA",
        "title": "Continued Presence Grants FY2015–FY2022",
        "summary": "Continued Presence grants rose from 272 in FY2015 to 1,002 in FY2022 — a 268% increase. HSI initiates the majority (approximately 68%) of CP requests. Labor trafficking cases account for roughly 40% of CP grants in recent years, reflecting increased DOL-HSI joint enforcement.",
        "source": "DHS Blue Campaign Annual Reports 2015–2022",
    },
    # ── U-Visa Program (USA) ──────────────────────────────────────────────
