    # ── Identification Challenges and Best Practices ──────────────────────
    {
        "type": "advisory",
        "jurisdiction": "international",
        "title": "UNODC — Challenges in Identifying Labour Trafficking Victims",
        "summary": "UNODC's 2022 Global Report on Trafficking in Persons identified four key barriers to labour trafficking victim identification: victims' fear of deportation, lack of trust in authorities, language barriers, and economic dependency on traffickers. Countries with the highest identification rates — Netherlands, USA, UK — share: dedicated victim support workers embedded in law enforcement teams, trauma-informed interview protocols, and robust immigration relief pathways independent of prosecution.",
        "source": "UNODC Global Report on Trafficking in Persons 2022, Chapter 5",
    },
    {
        "type": "advisory",
        "jurisdiction": "USA",
        "title": "Polaris Project — 2023 Trafficking Survivor Needs Assessment",
        "summary": "Polaris's 2023 assessment of 1,400 trafficking survivors found the top 5 unmet needs: (1) stable housing (87%); (2) employment support (79%); (3) mental health services (74%); (4) immigration legal aid (68%); (5) financial literacy and banking access (61%). Survivors with access to comprehensive case management services were 3.2 times more likely to maintain stable housing 12 months post-rescue than those without case management.",
        "source": "Polaris Project, Survivor Needs Assessment (2023); National Human Trafficking Hotline Data Brief Q4 2023",
    },
    {
        "type": "advisory",
        "jurisdiction": "EU",
        "title": "FRA — Obstacles Faced by Trafficking Victims in Access to Justice",
        "summary": "The EU Fundamental Rights Agency's 2019 report 'Trafficking in Human Beings: Identifying Victims and Overcoming Obstacles' found that 63% of trafficking victims in 10 EU member states surveyed had not reported their situation to police. Main barriers: fear of reprisals (71%), distrust of police (54%), fear of deportation (49%), and lack of information about rights (44%). States with proactive NRM identification had significantly higher victim cooperation rates.",
        "source": "EU FRA, Trafficking in Human Beings: Identifying Victims and Overcoming Obstacles (2019); FRA Human Trafficking Reference Guide (2023)",
    },
